// Kegunaan file: Menyiapkan Axios untuk komunikasi browser dengan backend Laravel.
/**
 * Siapkan Axios untuk mengirim permintaan dari browser ke backend Laravel.
 * Axios juga mengirim token CSRF dari cookie agar permintaan formulir lebih aman.
 */

import axios from 'axios';
window.axios = axios;

window.axios.defaults.headers.common['X-Requested-With'] = 'XMLHttpRequest';

